import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const [mode,nativeArg,outputArg]=process.argv.slice(2);
assert.ok(['--write','--check'].includes(mode)&&nativeArg&&outputArg,'--write/--check <native acceptance> <review request>');
const resolve=p=>path.resolve(root,p),hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const json=p=>JSON.parse(fs.readFileSync(resolve(p),'utf8').replace(/^\uFEFF/,''));
