const history=['docs/evidence/d-gc-freeze-protocol-d49501bd26ef47a4ba1ad6d27f9c69fd.json','docs/evidence/a-gc-freeze-nil-reviewed-20261023.json','docs/evidence/a-gc-work-extraction-reviewed-20261023.json','scripts/system-backup-d-gc-freeze-review-request.mjs'];
const inputs=[nativeArg,sourceArg,...files,'scripts/system-backup-d-gc-freeze-candidate-validation.ps1','docs/evidence/d-finalizer-independent-review-requirements-20261023.json','docs/evidence/d-gc-finalizer-review-request-20261026.mjs',...history].map(pin);
const result={kind:'d_gc_finalizer_incremental_review_request.v1',source_sha256:native.source_sha256,source_files:native.source_files,requested_requirements:['F1','F2','F3','F4','F5','F6','F7','F8','F9','F10'],native_acceptance:pin(nativeArg),current_scope:'private exact-original-context/tx one-use completion and fixed concrete collector candidate; original public Collect owner unchanged',current_whole_tree_accepted:native.source_current_bytes_and_set_match,current_tagged_drill_delta_pending:native.current_input_drift??[],standalone_scope:{explicit_Go_sources:files.filter(f=>['download_retention_gc_freeze.go','download_retention_gc_freeze_test.go','download_retention_gc_freeze_a_test.go','download_retention_gc_finalize.go','download_retention_gc_finalize_test.go'].includes(path.basename(f))),native_stages:[19,20],default_vet:true,concrete_collector_certified_by_standalone:false},historical_receipts:{inputs:history.map(pin),current_code_approval_inherited:false,old_generator_current_command:false,reason:'Old generator correctly binds predecessor fixed SHA; use this exact new-source request rather than deleting its historical checks.'},production_wired:false,joint_real_grants_approved:false,complete_metadata_policy_approved:false,production_approved:false,actual_mysql:false,remote_contacted:false,dependencies_installed:false,inputs};
assert.equal(path.dirname(resolve(outputArg)),resolve('docs/evidence'));
if(mode==='--write')fs.writeFileSync(resolve(outputArg),JSON.stringify(result,null,2)+'\n',{flag:'wx'});else assert.deepEqual(json(outputArg),result);
console.log(`FINALIZER_REQUEST_OK source=${native.source_sha256} requirements=10 inherited_approval=no`);
